1|// What every move shares: canvas size, fonts, palette, the spec a run hands over, and a small motion kit (pure functions of time).
2|// A move lives in ./moves/<Name>.tsx and exports a component ({t, s}) and a function giving its length in seconds.
3|
4|import {loadFont as loadSans} from '@remotion/google-fonts/Geist';
5|import {loadFont as loadSerif} from '@remotion/google-fonts/InstrumentSerif';
6|import React from 'react';
7|import {Audio, Img, OffthreadVideo, Sequence, staticFile} from 'remotion';
8|
9|export const SANS = loadSans('normal', {weights: ['500'], subsets: ['latin']}).fontFamily;
10|export const SERIF = loadSerif('italic', {weights: ['400'], subsets: ['latin']}).fontFamily;
11|export const W = 1920;
12|export const H = 1080;
13|export const FPS = 30;
14|export const INK = '#101114';
15|export const ACCENTS = ['#ff3ea5', '#7c3aed', '#0866ff', '#06b6d4'];
16|
17|export type MoveId = 'wall' | 'camera' | 'throw' | 'iris' | 'behind' | 'thought' | `gen-${string}`; // gen-*: written by Muse Code (level 3)
18|
19|export type Spec = {
20|	move: MoveId;
21|	video: string; // files in the render's public folder
22|	still: string; // the frozen frame, 1920x1080, cropped like the video on screen (object-fit: cover)
23|	ad: string;
24|	adFirst: string; // the ad's first frame, 1920x1080
25|	freezeAt: number; // seconds into the video
26|	adFrom?: number; // where the ad starts playing
27|	lines: string[];
28|	adSeconds?: number; // how much of the ad is shown after the bridge
29|	// Only when SAM 3.1 cut out a subject (moves of level 2), all in the 1920x1080 frame of `still`:
30|	cutout?: string; // the subject alone, PNG with alpha, 1920x1080, same place as in the still
31|	plate?: string; // the still with the subject filled in (optional; moves fall back to a blurred still)
32|	box?: [number, number, number, number]; // x0, y0, x1, y1 of the subject
33|	center?: [number, number]; // centre of mass of the mask
34|	face?: [number, number]; // a point near the top of the subject (head), for moves that aim at the face
35|	voices?: {file: string; voice?: string}[]; // the lines said by a system voice (macOS `say`, no AI call), one file per line; absent: text only
36|};
37|
38|export type MoveProps = {t: number; s: Spec};
39|
40|// ---------------------------------------------------------------- small motion kit (pure functions of time)
41|
42|export const clamp = (x: number) => Math.max(0, Math.min(1, x));
43|export const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
44|export const seg = (t: number, a: number, d: number) => clamp((t - a) / d);
45|export const out3 = (x: number) => 1 - Math.pow(1 - clamp(x), 3);
46|export const inOut = (x: number) => {
47|	const k = clamp(x);
48|	return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
49|};
50|/** From 0 to 1 with an overshoot. */
51|export const sp = (u: number, w = 15, d = 6.5) => (u <= 0 ? 0 : 1 - Math.exp(-d * u) * Math.cos(w * u));
52|/** A pendulum that dies out. */
53|export const swing = (u: number, amp: number, w = 7, d = 1.7) => (u <= 0 ? 0 : amp * Math.exp(-d * u) * Math.sin(w * u));
54|export const fr = (s: number) => Math.round(s * FPS);
55|export const mix = (a: string, b: string, k: number) => {
56|	const p = (c: string) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
57|	const [x, y] = [p(a), p(b)];
58|	return `rgb(${x.map((v, i) => Math.round(lerp(v, y[i], clamp(k)))).join(',')})`;
59|};
60|let canvas: CanvasRenderingContext2D | null = null;
61|export const measure = (text: string, font: string, spacing = 0) => {
62|	if (!canvas) canvas = document.createElement('canvas').getContext('2d');
63|	const c = canvas as CanvasRenderingContext2D & {letterSpacing: string};
64|	c.font = font;
65|	c.letterSpacing = `${spacing}px`;
66|	return c.measureText(text).width;
67|};
68|
69|// ---------------------------------------------------------------- the line: words land one by one at reading pace, the last word in serif and colour
70|
71|export type Wd = {w: string; at: number; serif: boolean; color?: string};
72|export const READ = 0.24; // seconds per word, a calm speaking pace
73|export const lineWords = (text: string, at: number, accent: string): Wd[] => {
74|	const parts = text.split(' ').filter(Boolean);
75|	return parts.map((w, i) => ({w, at: at + i * READ, serif: i === parts.length - 1, color: i === parts.length - 1 ? accent : undefined}));
76|};
77|export const lineLen = (text: string) => Math.max(1.1, text.split(' ').filter(Boolean).length * READ + 0.5);
78|
79|export const Words: React.FC<{t: number; words: Wd[]; size: number; x: number; y: number}> = ({t, words, size, x, y}) => {
80|	const spc = size * -0.02;
81|	const font = (w: Wd) => (w.serif ? `italic 400 ${size * 1.14}px ${SERIF}` : `500 ${size}px ${SANS}`);
82|	const items = words.map((w) => ({w, k: out3(seg(t, w.at, 0.36)), width: measure(w.w, font(w), w.serif ? 0 : spc)}));
83|	const gap = size * 0.27;
84|	const total = items.reduce((sum, it, i) => sum + (it.width + (i ? gap : 0)) * it.k, 0);
85|	let cur = x - total / 2;
86|	return (
87|		<>
88|			{items.map(({w, k, width}, i) => {
89|				if (i) cur += gap * k;
90|				const left = cur;
91|				cur += width * k;
92|				if (k <= 0) return null;
93|				return (
94|					<div key={i} style={{position: 'absolute', left, top: y, whiteSpace: 'nowrap', lineHeight: 1, fontFamily: w.serif ? SERIF : SANS, fontStyle: w.serif ? 'italic' : 'normal', fontSize: w.serif ? size * 1.14 : size, fontWeight: w.serif ? 400 : 500, letterSpacing: w.serif ? 0 : spc, color: mix('#b5b5ba', w.color ?? INK, seg(t, w.at + 0.1, 0.34)), transformOrigin: 'left center', transform: `translateY(-50%) translateY(${(1 - k) * size * 0.26}px) scale(${lerp(0.84, 1, k)})`, opacity: Math.min(1, k * 1.5), filter: k < 0.98 ? `blur(${(1 - k) * 7}px)` : 'none'}}>
95|						{w.w}
96|					</div>
97|				);
98|			})}
99|		</>
100|	);
101|};
102|
103|export const Rings: React.FC<{t: number; at: number; colors: string[]}> = ({t, at, colors}) => (
104|	<svg width={W} height={H} style={{position: 'absolute', inset: 0, overflow: 'visible'}}>
105|		{colors.map((c, i) => {
106|			const u = (t - at - i * 0.08) / 0.6;
107|			if (u <= 0 || u >= 1) return null;
108|			return <circle key={i} cx={W / 2} cy={H / 2} r={out3(u) * 1150} fill="none" stroke={c} strokeWidth={(1 - u) * 34} />;
109|		})}
110|	</svg>
111|);
112|
113|export const Clip: React.FC<{src: string; at: number; len: number; from?: number; muted?: boolean; volume?: number | ((f: number) => number)}> = ({src, at, len, from = 0, muted, volume = 1}) => (
114|	<Sequence from={fr(at)} durationInFrames={Math.max(1, fr(at + len) - fr(at)) + 1} layout="none">
115|		<OffthreadVideo src={staticFile(src)} startFrom={fr(from)} muted={muted} volume={volume} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover'}} />
116|	</Sequence>
117|);
118|export const Pic: React.FC<{src: string}> = ({src}) => <Img src={staticFile(src)} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover'}} />;
119|export const Click: React.FC<{at: number; v?: number}> = ({at, v = 0.6}) => (
120|	<Sequence from={fr(at)} durationInFrames={fr(0.5)} layout="none">
121|		<Audio src={staticFile('click.ogg')} volume={v} />
122|	</Sequence>
123|);
